t.guides["forever/legacy/legacy-challenges"] = (function() return {
		["Adventure: explore the world map"] = "Aventure : explorer la carte du monde",
		["Adventure: {npc:16042}"] = "Aventure : {npc:16042}",
		["Classes give 27 points: every class reaching 25, 45 and 60. They count once per class across your account, so a second character of a class you already raised adds nothing; a new class does. The first character to reach 25 usually unlocks the Legacy System itself."] = "Les classes donnent 27 points : chaque classe atteignant les niveaux 25, 45 et 60. Elles comptent une fois par classe sur tout votre compte : un deuxième personnage d'une classe déjà montée n'ajoute rien, une nouvelle classe si. Le premier personnage à atteindre le niveau 25 débloque généralement le système d'Héritage lui-même.",
		["Classes: level 25"] = "Classes : niveau 25",
		["Classes: level 45"] = "Classes : niveau 45",
		["Classes: level 60"] = "Classes : niveau 60",
		["Dire Maul East"] = "Hache-tripes Est",
		["Dire Maul North"] = "Hache-tripes Nord",
		["Dire Maul West"] = "Hache-tripes Ouest",
		["Dungeons: level 15-25"] = "Donjons : niveau 15-25",
		["Dungeons: level 26-45"] = "Donjons : niveau 26-45",
		["Dungeons: level 46-60"] = "Donjons : niveau 46-60",
		["Each crafting profession gives 3 points, at 150, 225 and 300. Ranks count once per profession across your account. Follow the Polestar guide \"{skill:171} 1-300\" (Professions). A crafting profession at 150 also unlocks the Legacy System."] = "Chaque métier d'artisanat donne 3 points, à 150, 225 et 300. Les rangs comptent une fois par métier sur tout votre compte. Suivez le guide Polestar \"{skill:171} 1-300\" (Métiers). Un métier d'artisanat à 150 débloque aussi le système d'Héritage.",
		["Follow the Polestar guide \"{skill:164} 1-300\" (Professions)."] = "Suivez le guide Polestar \"{skill:164} 1-300\" (Métiers).",
		["Follow the Polestar guide \"{skill:165} 1-300\" (Professions)."] = "Suivez le guide Polestar \"{skill:165} 1-300\" (Métiers).",
